// ==========================================
// DAILY FIVE
//
// Five people a day, picked the same way for
// everybody. Rank them worst -> best, lock it
// in, then see how close you were to the
// community ranking.
//
// Requires people.js (generated by tools/build.mjs)
// to be loaded first.
// ==========================================


// ------------------------------------------
// CONFIG
// ------------------------------------------

const PEOPLE_PER_DAY = 5;
const STORAGE_PREFIX = "rankdle:v1:";

// Counts up from here: #1 was January 1st, 2026.
const PUZZLE_EPOCH = Date.UTC(2026, 0, 1);

// Anything above this width plays as a desktop
// (horizontal number line, cards side by side).
const DESKTOP_QUERY = "(min-width: 641px)";


// ------------------------------------------
// STATE
// ------------------------------------------

const state = {
    key: dayKey(new Date()),
    people: [],          // today's five, in the order they are shown
    locked: false,
    selected: null,      // card picked for tap-to-swap
    lastDrag: 0,         // timestamp, so a drag is not also read as a tap
    dragged: null
};


// ------------------------------------------
// DAILY SEED
// ------------------------------------------

function dayKey(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");

    return `${year}-${month}-${day}`;
}


// Same date -> same number, so everyone
// gets the same five that day.
function dayNumber(key) {
    const [year, month, day] = key.split("-").map(Number);

    return Math.round(Date.UTC(year, month - 1, day) / 86400000);
}


// "#1", "#2", ... for the headline in the results.
function puzzleNumber(key) {
    return dayNumber(key) - Math.round(PUZZLE_EPOCH / 86400000) + 1;
}


// mulberry32: tiny deterministic random generator.
function makeRandom(seed) {
    let a = seed >>> 0;

    return function () {
        a = (a + 0x6d2b79f5) >>> 0;

        let t = Math.imul(a ^ (a >>> 15), 1 | a);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;

        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}


function shuffle(list, random) {
    for (let i = list.length - 1; i > 0; i--) {

        const j = Math.floor(random() * (i + 1));

        [list[i], list[j]] = [list[j], list[i]];
    }

    return list;
}


function pickDaily(key) {
    const random = makeRandom(dayNumber(key) * 7919);

    return shuffle([...ROSTER], random).slice(0, PEOPLE_PER_DAY);
}


// ------------------------------------------
// STORAGE
// ------------------------------------------

function loadResult(key) {
    try {
        const raw = localStorage.getItem(STORAGE_PREFIX + key);

        return raw ? JSON.parse(raw) : null;
    } catch (error) {
        return null;
    }
}


function saveResult(key, result) {
    try {
        localStorage.setItem(STORAGE_PREFIX + key, JSON.stringify(result));
    } catch (error) {
        // Private browsing - the game still works, it just forgets.
    }
}


// ?reset=1 wipes today so you can play again while testing.
function handleReset() {
    const params = new URLSearchParams(window.location.search);

    if (!params.has("reset")) {
        return;
    }

    localStorage.removeItem(STORAGE_PREFIX + state.key);

    params.delete("reset");

    const query = params.toString();

    history.replaceState(
        {},
        "",
        window.location.pathname + (query ? `?${query}` : "")
    );
}


// ------------------------------------------
// HELPERS
// ------------------------------------------

function initialsFor(name) {
    const ignored = new Set(["the", "a", "an", "of", "and"]);

    const words = name
        .split(/\s+/)
        .filter((word) => word.length > 1 && !ignored.has(word.toLowerCase()));

    const source = words.length ? words : name.split(/\s+/);

    if (source.length === 1) {
        return source[0].slice(0, 2).toUpperCase();
    }

    return (source[0][0] + source[1][0]).toUpperCase();
}


function isDesktop() {
    return window.matchMedia(DESKTOP_QUERY).matches;
}


// The cards on screen are the source of truth for the
// order the player has built, so pull that order back
// into state before anyone reads it.
function todayFive() {

    const cards = [...container.children].filter(
        (card) => card.classList.contains("person-card")
    );

    if (cards.length && cards.length === state.people.length) {

        const byName = new Map(state.people.map((person) => [person.name, person]));
        const order = cards.map((card) => byName.get(card.dataset.name)).filter(Boolean);

        if (order.length === cards.length) {
            state.people = order;
        }
    }

    return [...state.people];
}


// The ranking the site treats as correct:
// lowest score on the left (least good).
function communityOrder() {
    return todayFive().sort((a, b) => a.score - b.score);
}


// How many of the 10 possible head-to-head calls you got right.
function agreementScore(yours, theirs) {
    const position = new Map(theirs.map((person, index) => [person.name, index]));

    let compared = 0;
    let agreed = 0;

    for (let i = 0; i < yours.length; i++) {
        for (let j = i + 1; j < yours.length; j++) {

            const a = position.get(yours[i].name);
            const b = position.get(yours[j].name);

            // Community cannot separate them - skip the pair.
            if (a === b) {
                continue;
            }

            compared++;

            if (a < b) {
                agreed++;
            }
        }
    }

    return compared ? Math.round((agreed / compared) * 100) : 100;
}


function verdictFor(score) {
    if (score === 100) return ["Flawless.", "Every single pair, correct."];
    if (score >= 80) return ["Great call.", "The community agrees with most of it."];
    if (score >= 60) return ["Solid.", "Mostly right, with a few swings."];
    if (score >= 40) return ["Mixed feelings.", "About half your calls landed."];
    if (score >= 20) return ["Bold takes.", "The community went the other way a lot."];
    return ["Yikes.", "You and the community barely overlap."];
}


function formatDate(date) {
    return new Intl.DateTimeFormat("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric"
    }).format(date);
}


// ------------------------------------------
// RENDERING
// ------------------------------------------

const container = document.getElementById("people-container");
const submitButton = document.getElementById("submit-ranking");
const playedNote = document.getElementById("played-note");
const modal = document.getElementById("result-modal");


function cardMarkup(person, index) {
    const photo = person.image
        ? `<img src="${person.image}" alt="" loading="lazy">`
        : "";

    return `
        <span class="rank-badge">${index + 1}</span>
        <div class="portrait">
            <span class="initials" aria-hidden="true">${initialsFor(person.name)}</span>
            ${photo}
        </div>
        <span class="person-name">${person.name}</span>
        <span class="person-years">${person.years}</span>
    `;
}


function render() {

    container.innerHTML = "";

    state.people.forEach((person, index) => {

        const card = document.createElement("div");

        card.className = "person-card";
        card.draggable = !state.locked;
        card.tabIndex = 0;
        card.dataset.name = person.name;
        card.innerHTML = cardMarkup(person, index);

        const image = card.querySelector("img");

        if (image) {
            image.addEventListener("error", () => {
                card.classList.add("no-photo");
            });
        }

        container.appendChild(card);

    });

    updateBadges();
    updateLockState();
    positionTicks();
}


// Keeps the 1..5 badges (and the accessible label)
// in sync with wherever the cards have been dragged.
function updateBadges() {

    [...container.children].forEach((card, index) => {

        const badge = card.querySelector(".rank-badge");

        if (badge) {
            badge.textContent = index + 1;
        }

        card.setAttribute(
            "aria-label",
            `Rank ${index + 1}: ${card.dataset.name}. Press the arrow keys to move it.`
        );

    });
}


function updateLockState() {

    container.classList.toggle("locked", state.locked);

    [...container.children].forEach((card) => {
        card.draggable = !state.locked;
        card.classList.toggle("selected", card === state.selected);
    });

    submitButton.textContent = state.locked ? "SEE RESULT" : "LOCK IN";
    playedNote.hidden = !state.locked;
}


// ------------------------------------------
// NUMBER LINE
//
// The five ticks sit under the five cards, so
// they follow the cards around on resize.
// ------------------------------------------

const numberLine = document.querySelector(".number-line");
const line = numberLine.querySelector(".line");
const ticks = [...numberLine.querySelectorAll(".tick")];


function positionTicks() {

    if (!isDesktop() || !container.children.length) {
        return;
    }

    const base = numberLine.getBoundingClientRect();
    const cards = [...container.children];
    const centers = [];

    cards.forEach((card, index) => {

        const box = card.getBoundingClientRect();
        const center = box.left + box.width / 2 - base.left;

        centers.push(center);

        if (ticks[index]) {
            ticks[index].style.left = `${center}px`;
        }

    });

    // The line runs from the first tick to the last one.
    line.style.left = `${centers[0]}px`;
    line.style.right = `${base.width - centers[centers.length - 1]}px`;
}


let resizeTimer = null;

window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(positionTicks, 100);
});


// ------------------------------------------
// REORDERING
// ------------------------------------------

function clearSelection() {
    state.selected = null;
    updateLockState();
}


function swapCards(a, b) {

    const placeholder = document.createComment("swap");

    container.insertBefore(placeholder, a);
    container.insertBefore(a, b);
    container.insertBefore(b, placeholder);
    container.removeChild(placeholder);

    updateBadges();
    positionTicks();
}


// Tap one card, then another, to swap them.
// This is what makes the game playable on touch
// screens, where dragging does not work.
container.addEventListener("click", (event) => {

    const card = event.target.closest(".person-card");

    if (!card || state.locked) {
        return;
    }

    // A drag ends with a click - ignore it.
    if (Date.now() - state.lastDrag < 300) {
        return;
    }

    if (!state.selected) {
        state.selected = card;
    } else if (state.selected === card) {
        state.selected = null;
    } else {
        swapCards(state.selected, card);
        state.selected = null;
    }

    updateLockState();
});


container.addEventListener("keydown", (event) => {

    if (state.locked) {
        return;
    }

    const card = event.target.closest(".person-card");

    if (!card) {
        return;
    }

    const back = event.key === "ArrowLeft" || event.key === "ArrowUp";
    const forward = event.key === "ArrowRight" || event.key === "ArrowDown";

    if (!back && !forward) {
        return;
    }

    event.preventDefault();

    const sibling = back
        ? card.previousElementSibling
        : card.nextElementSibling;

    if (!sibling || !sibling.classList.contains("person-card")) {
        return;
    }

    swapCards(card, sibling);
    card.focus();
});


// ------------------------------------------
// DRAGGING
// ------------------------------------------

document.addEventListener("dragstart", (event) => {

    const card = event.target.closest(".person-card");

    if (!card || state.locked) {
        event.preventDefault();
        return;
    }

    state.dragged = card;
    card.classList.add("dragging");

    if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", card.dataset.name);
    }
});


document.addEventListener("dragend", () => {

    if (!state.dragged) {
        return;
    }

    state.dragged.classList.remove("dragging");
    state.dragged = null;
    state.lastDrag = Date.now();

    updateBadges();
    positionTicks();
});


container.addEventListener("dragover", (event) => {

    if (!state.dragged) {
        return;
    }

    event.preventDefault();

    if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "move";
    }

    const cards = [...container.querySelectorAll(".person-card:not(.dragging)")];

    if (!cards.length) {
        return;
    }

    // Nearest card to the pointer, then drop before or
    // after it depending on which half the pointer is in.
    let nearest = null;
    let nearestDistance = Infinity;

    for (const card of cards) {

        const box = card.getBoundingClientRect();

        const dx = event.clientX - (box.left + box.width / 2);
        const dy = event.clientY - (box.top + box.height / 2);
        const distance = dx * dx + dy * dy;

        if (distance < nearestDistance) {
            nearestDistance = distance;
            nearest = card;
        }
    }

    const box = nearest.getBoundingClientRect();

    const before = isDesktop()
        ? event.clientX < box.left + box.width / 2
        : event.clientY < box.top + box.height / 2;

    container.insertBefore(state.dragged, before ? nearest : nearest.nextSibling);
});


container.addEventListener("drop", (event) => {
    event.preventDefault();
});


// ------------------------------------------
// THE REVEAL
// ------------------------------------------

function rowMarkup(person, position, marked) {
    const photo = person.image
        ? `<img src="${person.image}" alt="" loading="lazy">`
        : `<span class="row-initials">${initialsFor(person.name)}</span>`;

    return `
        <li class="${marked ? "row-correct" : ""}">
            <span class="row-rank">${position}</span>
            <span class="row-portrait">${photo}</span>
            <span class="row-text">
                <span class="row-name">${person.name}</span>
                <span class="row-role">${person.role}</span>
            </span>
            ${marked ? '<span class="row-check" title="You had this one right">&#10003;</span>' : ""}
        </li>
    `;
}


function showResult(yours, score) {

    const community = communityOrder();
    const [title, blurb] = verdictFor(score);

    document.getElementById("result-kicker").textContent =
        `DAILY FIVE #${puzzleNumber(state.key)} \u00b7 ${formatDate(new Date(state.key + "T12:00:00"))}`;

    document.getElementById("result-title").textContent = title;

    document.getElementById("result-score").textContent =
        `${score}% agreement with the community. ${blurb}`;

    document.getElementById("your-list").innerHTML = yours
        .map((person, index) =>
            rowMarkup(person, index + 1, community[index]?.name === person.name)
        )
        .join("");

    document.getElementById("community-list").innerHTML = community
        .map((person, index) => rowMarkup(person, index + 1, false))
        .join("");

    document.getElementById("result-note").textContent =
        "Come back tomorrow for a new five.";

    modal.hidden = false;
    document.body.classList.add("modal-open");

    document.getElementById("result-close").focus();
}


function hideResult() {
    modal.hidden = true;
    document.body.classList.remove("modal-open");
}


document.getElementById("result-close").addEventListener("click", hideResult);

modal.addEventListener("click", (event) => {
    if (event.target === modal) {
        hideResult();
    }
});

document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !modal.hidden) {
        hideResult();
    }
});


// ------------------------------------------
// LOCK IN
// ------------------------------------------

submitButton.addEventListener("click", () => {

    const yours = todayFive();

    if (state.locked) {
        const saved = loadResult(state.key);
        showResult(yours, saved ? saved.score : agreementScore(yours, communityOrder()));
        return;
    }

    const score = agreementScore(yours, communityOrder());

    saveResult(state.key, { order: yours.map((person) => person.name), score });

    state.locked = true;
    clearSelection();
    updateLockState();

    showResult(yours, score);
});


// ------------------------------------------
// START
// ------------------------------------------

handleReset();

document.getElementById("today-date").textContent =
    formatDate(new Date()).toUpperCase();

if (!Array.isArray(ROSTER) || ROSTER.length < PEOPLE_PER_DAY) {

    container.innerHTML =
        "<p class='hint'>No people loaded. Run <code>node tools/build.mjs</code> first.</p>";

} else {

    const saved = loadResult(state.key);

    if (saved && Array.isArray(saved.order)) {

        const restored = saved.order
            .map((name) => ROSTER.find((person) => person.name === name))
            .filter(Boolean);

        if (restored.length === PEOPLE_PER_DAY) {
            state.people = restored;
            state.locked = true;
        }
    }

    if (!state.people.length) {
        state.people = pickDaily(state.key);
    }

    render();

    // Cards can change height once the portraits load.
    container.addEventListener("load", positionTicks, true);
    window.addEventListener("load", positionTicks);
}
